import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDateOption = {
  value: string;
  label: string;
  getDate: () => Date;
};

function startOfToday(): Date {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  return date;
}

function daysBeforeToday(count: number): Date {
  const date = startOfToday();
  date.setDate(date.getDate() - count);
  return date;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return (
    a !== null &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

const reportDateOptions: ReportDateOption[] = [
  { value: 'today', label: 'Сегодня', getDate: () => daysBeforeToday(0) },
  { value: 'yesterday', label: 'Вчера', getDate: () => daysBeforeToday(1) },
  { value: 'week-ago', label: 'Неделя назад', getDate: () => daysBeforeToday(7) },
];

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(defaultValue);

  const selectDate = (nextValue: Date | null) => {
    setSelectedDate(nextValue);
    onChange?.(nextValue);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div role="group" aria-label="Быстрый выбор даты" style={{ display: 'flex', gap: '8px' }}>
        {reportDateOptions.map((option) => {
          const optionDate = option.getDate();
          return (
            <JxChip
              key={option.value}
              active={isSameDay(selectedDate, optionDate)}
              aria-pressed={isSameDay(selectedDate, optionDate)}
              onClick={() => selectDate(optionDate)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={selectDate} />
    </div>
  );
}

